// Schriften fuer das Jana-Display, im GFX-Format von Adafruit.
//
// Erzeugt aus Inter 4.1 (SIL Open Font License, github.com/rsms/inter) mit
// fontconvert aus der Adafruit-GFX-Library:
//
//   fontconvert Inter-Regular.ttf   6 32 252   -> S_KLEIN
//   fontconvert Inter-Regular.ttf   9 32 252   -> S_NORMAL
//   fontconvert Inter-SemiBold.ttf 10 32 252   -> S_FETT
//   fontconvert Inter-SemiBold.ttf 13 32 252   -> S_GROSS
//   fontconvert Inter-SemiBold.ttf 24 48  58   -> S_UHR    (nur Ziffern und Doppelpunkt)
//   fontconvert Inter-SemiBold.ttf 44 48  58   -> S_RIESIG (nur Ziffern und Doppelpunkt)
//
// Zeichen 32 bis 252 decken Latin-1 ab, also auch ä ö ü Ä Ö Ü ß. Die
// eingebauten Schriften von TFT_eSPI kennen nur ASCII, deshalb stand auf
// dem Display bis Version 0.1.7 "Fruehstueck" und "faellig".
//
// Die Uhr-Schriften enthalten bewusst nur 0-9 und ':'. Eine volle 44-Punkt-
// Schrift waere 40 KB gross, die Ziffern allein sind 3,7 KB.
#pragma once
#include <TFT_eSPI.h>

